function safeSet(key, val) {
  if (typeof window.safeSetItem === 'function') {
    return window.safeSetItem(key, val);
  }
  try {
    localStorage.setItem(key, val);
    return true;
  } catch (e) {
    console.warn('Backup storage error:', e);
    return false;
  }
}
