const panel=document.createElement('section');panel.id='backupRestorePanel';panel.className='backup-restore-panel';panel.innerHTML=`<div><span class="backup-kicker">DATA SAFETY</span><h2>Backup & Restore</h2><p>Download a JSON backup of bookings, tour edits, category images and settings, or drag & drop a backup file here to restore.</p><div class="backup-meta"><span id="backupBookingsCount">0 bookings</span><span id="backupToursCount">0 tours</span><span id="backupLastTime">No backup created yet</span></div></div><div class="backup-actions"><button class="primary" id="createBackupBtn">↓ Create Backup</button><button class="restore-btn" id="restoreBackupBtn">↥ Restore Backup</button><input id="restoreBackupFile" type="file" accept="application/json,.json" hidden></div><div id="backupStatus" class="backup-status"></div>`;const dg=overview.querySelector('.dashboard-grid');if(dg)dg.before(panel);else overview.appendChild(panel);const $id=id=>document.getElementById(id);function readArray(key){try{const v=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(v)?v:[]}catch{return[]}}function updateMeta(){const b=readArray('phoenixBookings'),t=readArray('phoenixAdminTours'),last=localStorage.getItem('phoenixLastBackup'),rest=localStorage.getItem('phoenixLastRestore');const bEl=$id('backupBookingsCount'),tEl=$id('backupToursCount'),lEl=$id('backupLastTime');if(bEl)bEl.textContent=`${b.length} booking${b.length===1?'':'s'}`;if(tEl)tEl.textContent=`${t.length} tour${t.length===1?'':'s'}`;if(lEl){if(last)lEl.textContent=`Last backup: ${new Date(last).toLocaleString()}`;else if(rest)lEl.textContent=`Last restored: ${new Date(rest).toLocaleString()}`;else lEl.textContent='No backup created yet'}}window.updateBackupMeta=updateMeta;let statusTimer=null;function status(m,type='ok'){const el=$id('backupStatus');if(!el)return;el.textContent=m;el.className=`backup-status show ${type}`;clearTimeout(statusTimer);statusTimer=setTimeout(()=>{if(el)el.className='backup-status'},6000)}function createBackup(){try{const now=new Date().toISOString();localStorage.setItem('phoenixLastBackup',now);const storage={},data={};STORAGE_KEYS.forEach(k=>{const v=localStorage.getItem(k);if(v!==null){storage[k]=v;try{data[k]=JSON.parse(v)}catch{data[k]=v}}});const b=readArray('phoenixBookings'),t=readArray('phoenixAdminTours');const backupObj={format:'phoenix-tours-backup',version:2,createdAt:now,app:'Phoenix Tours Admin',summary:{bookingsCount:b.length,toursCount:t.length},storage,data};const blob=new Blob([JSON.stringify(backupObj,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`phoenix-tours-backup-${now.slice(0,10)}.json`;document.body.appendChild(a);a.click();setTimeout(()=>{a.remove();URL.revokeObjectURL(u)},1000);updateMeta();status('Backup created and downloaded successfully.','ok')}catch(err){console.error(err);status('Could not create backup.','err')}}
function extractBackupData(parsed){if(!parsed||typeof parsed!=='object')return null;const result={bookings:null,tours:null,settings:null,categoryImages:null,homepageCMS:null,landingCMS:null,createdAt:null};if(Array.isArray(parsed)){if(!parsed.length)return null;if(parsed[0].packages||parsed[0].category)result.tours=JSON.stringify(parsed);else result.bookings=JSON.stringify(parsed);return result}const sources=[parsed.storage,parsed.data,parsed].filter(s=>s&&typeof s==='object');function findVal(keys){for(const src of sources){for(const k of keys){if(src[k]!==undefined&&src[k]!==null)return src[k]}}return undefined}function serialize(val){if(val===undefined||val===null)return null;if(typeof val==='string'){const tr=val.trim();if((tr.startsWith('[')&&tr.endsWith(']'))||(tr.startsWith('{')&&tr.endsWith('}'))){try{JSON.parse(tr);return tr}catch{return JSON.stringify(val)}}return val}return JSON.stringify(val)}const rb=findVal(['phoenixBookings','bookings','bookingList']);if(rb!==undefined)result.bookings=serialize(rb);const rt=findVal(['phoenixAdminTours','tours','tourList','adminTours']);if(rt!==undefined)result.tours=serialize(rt);const rs=findVal(['phoenixSettings','settings','businessSettings']);if(rs!==undefined)result.settings=serialize(rs);const rc=findVal(['phoenixCategoryImages','categoryImages','categories','images']);if(rc!==undefined)result.categoryImages=serialize(rc);const rcms=findVal(['phoenixHomepageCMS','homepageCMS','cms']);if(rcms!==undefined)result.homepageCMS=serialize(rcms);const rlcms=findVal(['phoenixLandingCMS','landingCMS','landingPages']);if(rlcms!==undefined)result.landingCMS=serialize(rlcms);result.createdAt=parsed.createdAt||parsed.timestamp||findVal(['phoenixLastBackup','lastBackup']);if(result.bookings!==null||result.tours!==null||result.settings!==null||result.categoryImages!==null||result.homepageCMS!==null||result.landingCMS!==null)return result;return null}
let pendingRestoreData=null;
function applyRestore(data){const toApply=data||pendingRestoreData;if(!toApply)return;try{if(toApply.bookings!==null)safeSet('phoenixBookings',toApply.bookings);if(toApply.tours!==null)safeSet('phoenixAdminTours',toApply.tours);if(toApply.settings!==null)safeSet('phoenixSettings',toApply.settings);if(toApply.categoryImages!==null)safeSet('phoenixCategoryImages',toApply.categoryImages);if(toApply.homepageCMS!==null)safeSet('phoenixHomepageCMS',toApply.homepageCMS);if(toApply.landingCMS!==null)safeSet('phoenixLandingCMS',toApply.landingCMS);if(toApply.createdAt)safeSet('phoenixLastBackup',toApply.createdAt);safeSet('phoenixLastRestore',new Date().toISOString());if(typeof window.reloadAdminDashboard==='function')window.reloadAdminDashboard();window.dispatchEvent(new CustomEvent('phoenix:data-restored'));if(typeof window.refreshCategoryEditor==='function')window.refreshCategoryEditor();if(typeof window.refreshHomepageCMS==='function')window.refreshHomepageCMS();if(typeof window.refreshLandingCMS==='function')window.refreshLandingCMS();updateMeta();const d=$id('restoreConfirmDialog');if(d&&d.open)d.close();const fi=$id('restoreBackupFile');if(fi)fi.value='';status('Backup restored successfully! Dashboard updated.','ok');setTimeout(()=>{try{location.reload()}catch{}},500)}catch(e){console.error(e);status('Error restoring data to storage.','err')}finally{pendingRestoreData=null}}
async function restoreFile(file){const fi=$id('restoreBackupFile');try{status('Reading backup file…');const text=await file.text();let parsed;try{parsed=JSON.parse(text)}catch{status('Invalid JSON file. Please select a valid Phoenix Tours JSON backup.','err');if(fi)fi.value='';return}const data=extractBackupData(parsed);if(!data){status('No Phoenix Tours records found in this backup file.','err');if(fi)fi.value='';return}pendingRestoreData=data;let bCount=0,tCount=0;try{if(data.bookings){const a=JSON.parse(data.bookings);bCount=Array.isArray(a)?a.length:0}}catch{}try{if(data.tours){const a=JSON.parse(data.tours);tCount=Array.isArray(a)?a.length:0}}catch{}const dialog=$id('restoreConfirmDialog');if(dialog&&typeof dialog.showModal==='function'){const fn=$id('restoreModalFilename'),dt=$id('restoreModalDate'),bk=$id('restoreModalBookings'),tr=$id('restoreModalTours'),st=$id('restoreModalSettings'),im=$id('restoreModalImages');if(fn)fn.textContent=file.name||'backup.json';if(dt)dt.textContent=data.createdAt?new Date(data.createdAt).toLocaleString():'Date not specified';if(bk){bk.textContent=`${bCount} booking${bCount===1?'':'s'}`;bk.style.display=data.bookings!==null?'inline-block':'none'}if(tr){tr.textContent=`${tCount} tour${tCount===1?'':'s'}`;tr.style.display=data.tours!==null?'inline-block':'none'}if(st){st.textContent=data.settings!==null?'✓ Settings included':'No settings';st.style.opacity=data.settings!==null?'1':'0.4'}if(im){im.textContent=data.categoryImages!==null?'✓ Category images':'No images';im.style.opacity=data.categoryImages!==null?'1':'0.4'}dialog.showModal()}else{applyRestore(data)}}catch(err){console.error(err);status('Could not read or restore backup file.','err');if(fi)fi.value=''}}
