const closeBtn=$id('closeRestoreModalBtn'),cancelBtn=$id('cancelRestoreModalBtn'),applyBtn=$id('applyRestoreBtn');if(closeBtn)closeBtn.onclick=cancelRestore;if(cancelBtn)cancelBtn.onclick=cancelRestore;if(applyBtn)applyBtn.onclick=()=>applyRestore();$id('createBackupBtn').onclick=createBackup;$id('restoreBackupBtn').onclick=()=>$id('restoreBackupFile').click();$id('restoreBackupFile').onchange=e=>{const f=e.target.files?.[0];if(f)restoreFile(f)};panel.ondragover=e=>{e.preventDefault();panel.classList.add('drag-over')};panel.ondragleave=()=>{panel.classList.remove('drag-over')};panel.ondrop=e=>{e.preventDefault();panel.classList.remove('drag-over');const f=e.dataTransfer?.files?.[0];if(f)restoreFile(f)};updateMeta();
